-- Questionnaire content and scoring choices live in PostgreSQL.
-- Published definitions are immutable; insert a new version for revisions.
CREATE TABLE screening_instruments (
  instrument_type VARCHAR(10) NOT NULL CHECK (instrument_type IN ('epds', 'phq9')),
  version VARCHAR(20) NOT NULL,
  definition JSONB NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (instrument_type, version),
  CHECK (definition->>'type' = instrument_type AND definition->>'version' = version)
);

CREATE UNIQUE INDEX uq_screening_instrument_active
  ON screening_instruments (instrument_type) WHERE is_active;

CREATE FUNCTION protect_screening_instrument_definition() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.instrument_type IS DISTINCT FROM OLD.instrument_type
     OR NEW.version IS DISTINCT FROM OLD.version
     OR NEW.definition IS DISTINCT FROM OLD.definition THEN
    RAISE EXCEPTION 'Published screening definitions are immutable; insert a new version';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_screening_instrument_definition_immutable
  BEFORE UPDATE ON screening_instruments FOR EACH ROW
  EXECUTE FUNCTION protect_screening_instrument_definition();

