-- Preserve any older historical assessments while enforcing versions on new rows.
ALTER TABLE screening_assessments ADD CONSTRAINT fk_screening_instrument_version
  FOREIGN KEY (instrument_type, instrument_version)
  REFERENCES screening_instruments (instrument_type, version) NOT VALID;
